"""Generate the plugin's English runtime texts from assets/texts.json."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def java_source(root=ROOT):
    data = json.loads((root / "assets/texts.json").read_text(encoding="utf-8"))
    literal = json.dumps(json.dumps(data, ensure_ascii=False, separators=(",", ":")), ensure_ascii=False)
    return ("// SPDX-License-Identifier: Apache-2.0\n"
            "// Generated by tools/texts.py from assets/texts.json.\n"
            "package kiosk.plugins.bing;\n"
            "final class Catalogue {\n    static final String JSON = " + literal + ";\n}\n")


def check_generated(root=ROOT):
    if (root / "src/kiosk/plugins/bing/Catalogue.java").read_text(encoding="utf-8") != java_source(root):
        raise ValueError("Runtime texts changed: run python tools/texts.py --write")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--write", action="store_true")
    args = parser.parse_args()
    if args.write:
        (ROOT / "src/kiosk/plugins/bing/Catalogue.java").write_text(java_source(), encoding="utf-8")
    check_generated()
    print("PASS: English runtime texts and generated Java match")
